const templates=new Map();
async function template156(model,unit){const key=model+unit;if(!templates.has(key))templates.set(key,trainAsset(model,unit).then(source=>{const g=source.clone(true);batchTrainStatics(g);g.updateMatrixWorld(true);return g;}).catch(e=>{templates.delete(key);throw e;}));return templates.get(key);}
function trim156(mesh,box){const src=mesh.geometry,raw=src.index?src.toNonIndexed():src.clone(),p=raw.attributes.position,kept=[],v=new THREE.Vector3(),a=new THREE.Vector3();for(let i=0;i<p.count;i+=3){v.set(0,0,0);for(let j=0;j<3;j++)v.add(a.fromBufferAttribute(p,i+j));v.multiplyScalar(1/3).applyMatrix4(mesh.matrixWorld);if(!box.containsPoint(v))kept.push(i,i+1,i+2);}if(kept.length===p.count){raw.dispose();return null;}const g=new THREE.BufferGeometry();for(const[key,a]of Object.entries(raw.attributes)){const values=new a.array.constructor(kept.length*a.itemSize);for(let i=0;i<kept.length;i++)for(let c=0;c<a.itemSize;c++)values[i*a.itemSize+c]=a.array[kept[i]*a.itemSize+c];g.setAttribute(key,new THREE.BufferAttribute(values,a.itemSize,a.normalized));}raw.dispose();if(kept.length){g.computeBoundingBox();g.computeBoundingSphere();}return g;}
export async function mountedTrain156(rig,model='NM22'){
 const [middle,cab]=await Promise.all([template156(model,'intermedio'),template156(model,'cabina')]);const root=new THREE.Group(),car=middle.clone(true),owned=[];root.name='Tren estacionado en vía de mantenimiento156';root.userData.installed156=true;root.add(car);
 const shift=rig.id==='running'?5.55:model==='MP82'?1.92:1.80;root.position.set(shift,0,-1.27);root.updateMatrixWorld(true);
 const box=rig.id==='doors'?new THREE.Box3(new THREE.Vector3(-1.63,1.08,-.18),new THREE.Vector3(1.63,3.62,.5)):rig.id==='running'?new THREE.Box3(new THREE.Vector3(-.76,0,-.55),new THREE.Vector3(.76,1.25,.5)):new THREE.Box3(new THREE.Vector3(-.62,.02,-.35),new THREE.Vector3(.62,1.05,.6));
 car.traverse(o=>{if(!o.isMesh)return;const g=trim156(o,box);if(g){o.geometry=g;owned.push(g);if(!g.attributes.position.count)o.visible=false;}});
 for(const [source,indices]of [[middle,[1,2,3,5,6,7]],[cab,[0,8]]])source.traverse(o=>{if(!o.isMesh||!o.visible)return;const inst=new THREE.InstancedMesh(o.geometry,o.material,indices.length);inst.name='Coches contiguos156';indices.forEach((i,n)=>{const reverse=model==='MP82'?i===0:i===8,m=new THREE.Matrix4().makeTranslation((i-4)*16.7,0,0);if(reverse&&source===cab)m.multiply(new THREE.Matrix4().makeRotationY(Math.PI));m.multiply(o.matrixWorld);inst.setMatrixAt(n,m);});inst.computeBoundingSphere();root.add(inst);});
 const platform=new THREE.Group();platform.name='Pasarela de servicio junto al tren156';const metal=new THREE.MeshStandardMaterial({name:'Acero galvanizado pasarela156',color:'#707e82',metalness:.75,roughness:.48}),yellow=new THREE.MeshStandardMaterial({name:'Pintura amarilla seguridad156',color:'#c9a03f',roughness:.62});const slab=new THREE.Mesh(new THREE.BoxGeometry(7,.12,1.9),metal);slab.position.set(0,1.04,1.25);platform.add(slab);for(const x of[-3,3])for(const z of[.5,2]){const leg=new THREE.Mesh(new THREE.BoxGeometry(.09,1.02,.09),metal);leg.position.set(x,.51,z);platform.add(leg);}const edge=new THREE.Mesh(new THREE.BoxGeometry(7,.015,.10),yellow);edge.position.set(0,1.11,.35);platform.add(edge);for(const o of platform.children)o.visible=rig.id==='doors';const tray=rig.parts.tray?.getWorldPosition(new THREE.Vector3());if(tray){const base=rig.id==='doors'?1.11:0;const h=Math.max(.12,tray.y-base-.03);for(const dx of[-.24,.24])for(const dz of[-.14,.14]){const leg=new THREE.Mesh(new THREE.BoxGeometry(.025,h,.025),metal);leg.position.set(tray.x+dx,base+h/2,tray.z+dz);platform.add(leg);}}refineSurfaceMaterials100(platform);
 return{root,platform,model,dispose(){root.removeFromParent();platform.removeFromParent();for(const g of owned)g.dispose();const mats=new Set();platform.traverse(o=>{o.geometry?.dispose();if(o.material)mats.add(o.material);});for(const m of mats)m.dispose();}};
}
export function mountRig156(rig){if(rig.mounted156)return;rig.mounted156=true;const named=new Set(Object.values(rig.parts));for(const o of [...rig.group.children])if(o.isMesh&&!named.has(o)||o.userData.anchor138==='static'&&rig.id==='doors')o.visible=false;
 if(rig.id==='doors'){rig.group.position.set(0,1.10,-.08);const s1=rig.parts.power;if(s1){s1.position.y=1.38;s1.position.z=.42;rig.homes.set(s1,s1.position.clone());}}else if(rig.id==='running'){rig.group.position.set(0,-.50,.10);for(const key of ['tray','meter']){const p=rig.parts[key];if(p){p.position.y+=.8;rig.homes.set(p,p.position.clone());}}const stand=rig.parts.stand;if(stand){stand.position.y=.65;rig.homes.set(stand,stand.position.clone());}}else{rig.group.scale.setScalar(.43);rig.group.position.set(0,.05,.12);}rig.group.updateMatrixWorld(true);
}
export function maintenanceBay156(){const root=new THREE.Group();root.name='Nave de mantenimiento con tren156';const concrete=new THREE.MeshStandardMaterial({name:'Piso concreto taller156',color:'#454e50',roughness:.86}),steel=new THREE.MeshStandardMaterial({name:'Acero riel taller156',color:'#697478',metalness:.8,roughness:.42}),wall=new THREE.MeshStandardMaterial({name:'Panel pared taller156',color:'#55646b',roughness:.75});const box=(x,y,z,w,h,d,m)=>{const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);root.add(o);};box(0,-.08,-1,190,.12,24,concrete);for(const z of[-2.18,-.38])box(0,.02,z,180,.07,.07,steel);for(let x=-80;x<=80;x+=12){for(const z of[-9,8])box(x,4,z,.22,8,.25,steel);box(x,8,-.5,.25,.24,18,steel);}box(0,4,-10,190,8,.12,wall);refineSurfaceMaterials100(root);return root;}
